-- Queues the 506 curated rounds from video_metadata.json and
-- video_metadata_deduplicated.json in the admin "Round videos" queue
-- (`youtube_round_videos`), where they wait for an admin to publish or remove
-- them. Nothing here writes to `videos`: a round already in the library, or
-- one an admin removed (`youtube_video_exclusions`), is skipped by each
-- statement's WHERE clause, so no published row is ever overwritten.
-- Generated by .github/scripts/queue-test-videos.ts (titles and channels from
-- YouTube oEmbed); applied once by .github/scripts/migrate-d1.ts.
-- apps/debate-ai.com/lib/videos/__tests__/curated-round-queue-migration.test.ts
-- runs it against the schema.
INSERT INTO youtube_round_videos (id, title, published_at, channel, views, description, style, tournament, round_level, aff, neg)
SELECT 'YgWRowupoWw', 'Tournament of Champions 2025 | Double Octofinals | JR Masterman WE vs Fairmont Preparatory SS | PFD', '2025-01-01', 'Outreach Debate', 0, 'Topic: Resolved: The United States federal government should substantially increase its investment in domestic nuclear energy.
Arguments: Theory, Fast
Neg 2NR args: Theory
Event: 2025 TOC Double Octos', 2, 'TOC', 'Doubles', 'JR Masterman WE', 'Fairmont Prep SS'
WHERE NOT EXISTS (SELECT 1 FROM videos WHERE video_id = 'YgWRowupoWw')
AND NOT EXISTS (SELECT 1 FROM youtube_video_exclusions WHERE video_id = 'YgWRowupoWw')
ON CONFLICT(id) DO UPDATE SET
description = CASE WHEN youtube_round_videos.description LIKE 'Topic: %' THEN excluded.description
WHEN youtube_round_videos.description LIKE '%Neg 2NR args:%' OR youtube_round_videos.description LIKE '%Aff 1AC args:%'
THEN youtube_round_videos.description
ELSE trim(youtube_round_videos.description || char(10) || char(10) || excluded.description) END,
updated_at = unixepoch();
--> statement-breakpoint
